import { EquipmentTier, ExerciseCategory, SessionType, PainRegion } from './store';

export type { ExerciseCategory };

type MainSessionType = Exclude<
  SessionType,
  'conditioning' | 'prehab' | 'flexibility' | 'custom' | 'upper_body' | 'lower_body' | 'full_body'
>;
export type InternalTier = 'bodyweight' | 'dumbbells' | 'fullgym';
const INTERNAL_TIERS: InternalTier[] = ['bodyweight', 'dumbbells', 'fullgym'];

export function toInternalTier(tier: EquipmentTier): InternalTier {
  if (tier === 'bands' || tier === 'bodyweight') return 'bodyweight';
  if (tier === 'kettlebells' || tier === 'dumbbells') return 'dumbbells';
  return 'fullgym';
}

export interface ExerciseTemplate {
  id: string;
  name: string;
  sets: number;
  reps: string;
  cue: string;
  suggestedLoad: string;
  category: ExerciseCategory;
  targetRegions: PainRegion[];
  videoId: string;
  // Optional metadata for filtering, display and future smart selection
  movementPattern?:
    | 'squat'
    | 'hinge'
    | 'push'
    | 'pull'
    | 'carry'
    | 'lunge'
    | 'rotation'
    | 'isometric'
    | 'conditioning'
    | 'mobility'
    | 'rehabilitation';
  primaryMuscle?: string;
  secondaryMuscles?: string[];
  equipmentRequired?: string;
  difficulty?: 'beginner' | 'intermediate' | 'advanced';
  isUnilateral?: boolean;
  injuryFriendlyAlternatives?: string[];
  swapAlternative?: {
    name: string;
    cue: string;
    suggestedLoad: string;
  };
  comfortVariant?: {
    name: string;
    cue: string;
    suggestedLoad: string;
    triggerRegions: PainRegion[];
  };
}

